#pragma once
#include "admission_observer.hpp"
namespace dmmu {
using admission::need;
struct Sample{bool reset=false,req=false,resp=false,incoming=false,enq=false,active=false,fast=false,prechecked=false,checked=false,checkedPrechecked=false,checkedFault=false,pageFault=false,accessFault=false;unsigned service=0,walker=0,mode=0,privilege=0;uint64_t va=0,pa=0;bool walkStart()const{return service==1&&walker==0;}};
inline void validate(const Sample&s){if(s.reset)return;need(s.service<3&&s.walker<4,"D MMU state range");need(!s.req||s.incoming,"D translation request without incoming fire");need(!s.resp||s.enq,"D translation response without translated enqueue");need(s.req||(!s.va&&!s.mode&&!s.privilege&&!s.active&&!s.fast),"D invalid request payload");need(s.resp||(!s.pa&&!s.pageFault&&!s.accessFault),"D invalid response payload");need(s.incoming||!s.prechecked,"D invalid incoming precheck");need(s.checked||(!s.checkedPrechecked&&!s.checkedFault),"D invalid checked payload");need(!s.prechecked||!s.req,"D prechecked ingress used demand translation");if(s.req){need(s.service==0,"D demand not idle");need(s.active==(s.mode!=0&&s.privilege!=3),"D active mode mismatch");need(s.resp==s.fast,"D fast/same-edge mismatch");need(s.fast||s.active,"D identity demand delayed");}if(s.resp&&!s.req)need(s.service==2,"D delayed response not replying");}
struct Counts{uint64_t cycles=0,requests=0,responses=0,tlbHits=0,identity=0,delayedStarts=0,delayedReplies=0,walkStarts=0,serviceWalking=0,serviceReplying=0,walkerBusy=0,precheckedIngress=0,checkedPrecheckedSuccess=0,checkedFaults=0,walkFaults=0;
 void add(const Sample&s){++cycles;requests+=s.req;responses+=s.resp;tlbHits+=s.req&&s.fast&&s.active;identity+=s.req&&s.fast&&!s.active;delayedStarts+=s.req&&!s.resp;delayedReplies+=s.resp&&!s.req;walkStarts+=s.walkStart();serviceWalking+=s.service==1;serviceReplying+=s.service==2;walkerBusy+=s.walker!=0;precheckedIngress+=s.incoming&&s.prechecked;checkedPrecheckedSuccess+=s.checked&&s.checkedPrechecked&&!s.checkedFault;checkedFaults+=s.checked&&s.checkedFault;walkFaults+=s.resp&&(s.pageFault||s.accessFault);}
 void json(std::ostream&o)const{o<<"{\"cycles\":"<<cycles<<",\"requests\":"<<requests<<",\"responses\":"<<responses<<",\"tlb_hits\":"<<tlbHits<<",\"identity_fast\":"<<identity<<",\"delayed_starts\":"<<delayedStarts<<",\"delayed_replies\":"<<delayedReplies<<",\"walk_starts\":"<<walkStarts<<",\"service_walking_cycles\":"<<serviceWalking<<",\"service_replying_cycles\":"<<serviceReplying<<",\"walker_nonidle_cycles\":"<<walkerBusy<<",\"prechecked_ingress_bypass\":"<<precheckedIngress<<",\"checked_prechecked_success\":"<<checkedPrecheckedSuccess<<",\"checked_faults\":"<<checkedFaults<<",\"walk_faults\":"<<walkFaults<<"}";}
};
struct Observer{std::ofstream trace;bool held=false,prevActive=false,inROI=false,roiSeen=false,outstanding=false,started=false;Sample prev;uint64_t priorCycle=0,seq=0,owner=0,ownerVa=0,ownerCycle=0,carryIn=0,carryOut=0;Counts all,roi;
 Observer(){if(const char*p=std::getenv("D_TRANSLATION_TRACE")){trace.open(p);need(bool(trace),"D trace open");}}
 void row(std::string s){if(trace){trace<<s<<'\n';need(bool(trace),"D trace write");}}
 void accept(const Sample&s,uint64_t edge,bool active){validate(s);if(active&&!inROI){need(!roiSeen,"D ROI duplicate");roiSeen=true;carryIn=outstanding;}if(!active&&inROI)carryOut=outstanding;inROI=active;all.add(s);if(active)roi.add(s);
  uint64_t id=0;
  if(s.req){need(!outstanding,"D duplicate outstanding demand");id=++seq;if(!s.resp){outstanding=true;started=false;owner=id;ownerVa=s.va;ownerCycle=edge;}}
  if(s.walkStart()){need(outstanding&&!started&&!s.req,"D missing/duplicate walk start owner");started=true;id=owner;}
  if(s.resp&&!s.req){need(outstanding&&started,"D delayed reply lacks demand/walk owner");id=owner;outstanding=false;started=false;}
  if(s.req||s.resp||s.walkStart()||s.prechecked||(s.checked&&s.checkedPrechecked)){
   std::ostringstream o;o<<"{\"event\":\"translation\",\"edge\":"<<edge<<",\"roi\":"<<active<<",\"request\":"<<s.req<<",\"response\":"<<s.resp<<",\"walk_start\":"<<s.walkStart()<<",\"id\":"<<id<<",\"va\":";if(s.req)o<<s.va;else if(s.walkStart()||(s.resp&&!s.req))o<<ownerVa;else o<<"null";o<<",\"pa\":";if(s.resp)o<<s.pa;else o<<"null";o<<",\"active_mode\":"<<s.active<<",\"fast\":"<<s.fast<<",\"mode\":"<<s.mode<<",\"privilege\":"<<s.privilege<<",\"service\":"<<s.service<<",\"walker\":"<<s.walker<<",\"page_fault\":"<<s.pageFault<<",\"access_fault\":"<<s.accessFault<<",\"prechecked_ingress\":"<<s.prechecked<<",\"checked_prechecked_success\":"<<(s.checked&&s.checkedPrechecked&&!s.checkedFault)<<"}";row(o.str());
  }
 }
 void sample(const Sample&s,uint64_t cycle,bool active){validate(s);if(s.reset){need(!held,"D reset after live sampling");return;}if(held){need(cycle==priorCycle+1,"D skipped edge");accept(prev,cycle,prevActive);}held=true;prev=s;priorCycle=cycle;prevActive=active;}
 void finish(std::ostream&o){need(!outstanding&&!inROI,"D terminal demand/ROI not drained");need(all.requests==all.responses&&all.delayedStarts==all.delayedReplies&&all.delayedStarts==all.walkStarts,"D whole demand conservation");need(roi.requests+carryIn==roi.responses+carryOut,"D ROI demand conservation");std::ostringstream q;q<<"{\"event\":\"summary\",\"all\":";all.json(q);q<<",\"roi\":";roi.json(q);q<<",\"roi_carry_in\":"<<carryIn<<",\"roi_carry_out\":"<<carryOut<<"}";row(q.str());if(trace)trace.flush();o<<"D_TRANSLATION_ADMISSION "<<q.str()<<'\n';}
};
template<class D> Sample read(D&d){Sample s;s.reset=d.get_backendReset();if(s.reset)return s;const auto ev=d.get_dataPathEvents();s.incoming=(ev>>13)&1;s.req=(ev>>14)&1;s.resp=(ev>>15)&1;s.enq=(ev>>16)&1;s.service=d.board$platform$physicalData_walkers_1$state;s.walker=d.board$platform$physicalData_walkers_1$walker$state;
 if(s.incoming)s.prechecked=d.board$platform$core$adapter$virtualRequests$head$$request$$precheckedLoad;
 if(s.req){s.va=d.get_dataPathRequest5Address();s.mode=(d.board$platform$core$adapter$virtualRequests$head$$context$$satp>>60)&15;s.privilege=d.board$platform$core$adapter$virtualRequests$head$$context$$dataPrivilege;s.active=d.board$platform$physicalData_walkers_1$activeMode;s.fast=d.board$platform$physicalData_walkers_1$fast;}
 if(s.resp){s.pa=d.get_dataPathRequest6Address();if(s.service==2){need(s.pa==d.board$platform$physicalData_walkers_1$savedResponse$$physicalAddress,"D delayed reply PA mismatch");s.pageFault=d.board$platform$physicalData_walkers_1$savedResponse$$pageFault;s.accessFault=d.board$platform$physicalData_walkers_1$savedResponse$$accessFault;}}
 s.checked=d.get_canonical$$checked$$valid()&&d.get_canonical$$checked$$ready();if(s.checked){s.checkedPrechecked=d.get_canonical$$checked$$bits$$precheckedLoad();s.checkedFault=d.get_canonical$$checkedFault();}validate(s);return s;}
}
